module hopper_exploration (\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] n,\n    input [2:0] D,\n    input [7:0] M,\n    input [7:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,\n    output reg [3:0] length,\n    output reg done\n);\n\n    // State encoding\n    localparam [1:0] STATE_IDLE    = 2'd0;\n    localparam [1:0] STATE_INIT    = 2'd1;\n    localparam [1:0] STATE_COMPUTE = 2'd2;\n    localparam [1:0] STATE_DONE    = 2'd3;\n\n    reg [1:0] state, next_state;\n    reg [2:0] i_reg, j_reg;\n    reg [7:0] dp [0:255];\n    reg [3:0] max_length;\n    reg [7:0] arr_reg [0:7];\n    reg [2:0] n_reg, D_reg;\n    reg [7:0] M_reg;\n    reg [7:0] mask;\n\n    integer k;  // For loops\n\n    // Absolute difference calculation\n    wire signed [7:0] arr_val_i = {arr_reg[i_reg][7], arr_reg[i_reg][6:0]};\n    wire signed [7:0] arr_val_j = {arr_reg[j_reg][7], arr_reg[j_reg][6:0]};\n    wire signed [8:0] signed_diff = arr_val_i - arr_val_j;\n    wire [7:0] abs_diff = signed_diff[8] ? -signed_diff[7:0] : signed_diff[7:0];\n\n    // Jump distance check\n    wire [3:0] distance = (i_reg > j_reg) ? (i_reg - j_reg) : (j_reg - i_reg);\n\n    // Jump validity\n    wire valid_jump = (j_reg != i_reg) &&\n                     (j_reg < n_reg) &&\n                     (abs_diff <= M_reg) &&\n                     (distance <= D_reg);\n\n    // FSM sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= STATE_IDLE;\n            done <= 1'b0;\n            length <= 4'd0;\n            max_length <= 4'd0;\n            i_reg <= 3'd0;\n            j_reg <= 3'd0;\n            mask <= 8'd0;\n            \n            // Initialize DP table\n            for (k = 0; k < 256; k = k + 1) begin\n                dp[k] <= 8'd0;\n            end\n\n            // Initialize array registers\n            for (k = 0; k < 8; k = k + 1) begin\n                arr_reg[k] <= 8'd0;\n            end\n\n            n_reg <= 3'd0;\n            D_reg <= 3'd0;\n            M_reg <= 8'd0;\n        end else begin\n            state <= next_state;\n\n            case (state)\n                STATE_IDLE: begin\n                    done <= 1'b0;\n                    length <= 4'd0;\n                end\n\n                STATE_INIT: begin\n                    // Store input array\n                    arr_reg[0] <= arr_0;\n                    arr_reg[1] <= arr_1;\n                    arr_reg[2] <= arr_2;\n                    arr_reg[3] <= arr_3;\n                    arr_reg[4] <= arr_4;\n                    arr_reg[5] <= arr_5;\n                    arr_reg[6] <= arr_6;\n                    arr_reg[7] <= arr_7;\n\n                    // Store parameters\n                    n_reg <= n;\n                    D_reg <= D;\n                    M_reg <= M;\n\n                    // Initialize DP with single-element sequences\n                    for (k = 0; k < 8; k = k + 1) begin\n                        if (k < n) begin\n                            dp[1 << k] <= 8'd1;\n                            max_length <= 4'd1;\n                        end else begin\n                            dp[1 << k] <= 8'd0;\n                        end\n                    end\n                end\n\n                STATE_COMPUTE: begin\n                    if (i_reg < n_reg) begin\n                        if (j_reg < n_reg) begin\n                            if (valid_jump) begin\n                                mask = (1 << i_reg) | (1 << j_reg);\n                                if (dp[mask] < (dp[1 << i_reg] + 1)) begin\n                                    dp[mask] <= dp[1 << i_reg] + 1;\n                                    if ((dp[1 << i_reg] + 1) > max_length) begin\n                                        max_length <= dp[1 << i_reg] + 1;\n                                    end\n                                end\n                            end\n                            j_reg <= j_reg + 3'd1;\n                        end else begin\n                            j_reg <= 3'd0;\n                            i_reg <= i_reg + 3'd1;\n                        end\n                    end\n                end\n\n                STATE_DONE: begin\n                    done <= 1'b1;\n                    length <= max_length;\n                end\n            endcase\n        end\n    end\n\n    // FSM next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            STATE_IDLE: next_state = start ? STATE_INIT : STATE_IDLE;\n            STATE_INIT: next_state = STATE_COMPUTE;\n            STATE_COMPUTE: next_state = (i_reg >= n_reg) ? STATE_DONE : STATE_COMPUTE;\n            STATE_DONE: next_state = STATE_IDLE;\n            default: next_state = STATE_IDLE;\n        endcase\n    end\n\nendmodule